// ── HAVAN FIAT — Retro Brazilian Street Scene ──
// Runtime: svg, w, h, bY, bCol, wc, ol, isN, mt, w1, w2, w3, sc
// Deterministic only — no Math.random()

const B = sc.sky1 || "#F4A460";
const Y = sc.acc  || "#E8D44D";
const G = sc.ground || "#8B7355";
const deep = sc.sky2 || "#FFDAB9";
const white = "#ffffff";
const ww = w / 900;

const sin = (t, amp = 1, freq = 1, phase = 0) => Math.sin(t * freq + phase) * amp;
const cos = (t, amp = 1, freq = 1, phase = 0) => Math.cos(t * freq + phase) * amp;
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

// ── DEFS ──
svg += `<defs>
  <filter id="fg" x="-50%" y="-50%" width="200%" height="200%">
    <feGaussianBlur stdDeviation="2" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
  </filter>
  <filter id="sg" x="-50%" y="-50%" width="200%" height="200%">
    <feGaussianBlur stdDeviation="1.2" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
  </filter>
  <filter id="sh" x="-20%" y="-20%" width="140%" height="140%">
    <feDropShadow dx="0" dy="2" stdDeviation="3" flood-color="#000" flood-opacity="0.3"/>
  </filter>
  <filter id="bf"><feGaussianBlur stdDeviation="1.5"/></filter>
  <radialGradient id="sunG" cx="50%" cy="50%" r="50%">
    <stop offset="0%" stop-color="${Y}" stop-opacity="0.95"/>
    <stop offset="60%" stop-color="${Y}" stop-opacity="0.2"/>
    <stop offset="100%" stop-color="${Y}" stop-opacity="0"/>
  </radialGradient>
  <linearGradient id="bldG" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#5B4A3A" stop-opacity="0.9"/>
    <stop offset="100%" stop-color="#3D2E1F" stop-opacity="0.95"/>
  </linearGradient>
  <linearGradient id="stripeG" x1="0" y1="0" x2="1" y2="0">
    <stop offset="0%" stop-color="${B}" stop-opacity="0.08"/>
    <stop offset="50%" stop-color="${B}" stop-opacity="0.25"/>
    <stop offset="100%" stop-color="${B}" stop-opacity="0.08"/>
  </linearGradient>
</defs>`;

// ── SUN ──
const sunX = w * 0.80;
const sunY = h * 0.18;
const sunR = (20 + 4 * w1) * ww;
if (!isN) {
  svg += `<circle cx="${sunX}" cy="${sunY}" r="${sunR * 2.2}" fill="url(#sunG)"/>`;
  svg += `<circle cx="${sunX}" cy="${sunY}" r="${sunR}" fill="#FFD27A" filter="url(#fg)"/>`;
} else {
  svg += `<circle cx="${sunX}" cy="${sunY}" r="${sunR}" fill="#E8E0D0" opacity="0.5" filter="url(#fg)"/>`;
}

// ── DRIFTING CLOUDS ──
for (let i = 0; i < 4; i++) {
  const cx = ((w * 1.2 * (0.1 + i * 0.25) - mt * 8 * (0.6 + i * 0.15)) % (w * 1.4) + w * 0.1);
  const cy = h * (0.08 + i * 0.05) + sin(mt * 0.3 + i * 0.7, 6);
  const rw = (40 + i * 18 + sin(mt * 0.5 + i, 8)) * ww;
  const rh = (12 + i * 5) * ww;
  svg += `<ellipse cx="${cx.toFixed(1)}" cy="${cy.toFixed(1)}" rx="${rw.toFixed(1)}" ry="${rh.toFixed(1)}" fill="${white}" opacity="${0.20 + i * 0.06}" filter="url(#bf)"/>`;
  svg += `<ellipse cx="${(cx - rw * 0.35).toFixed(1)}" cy="${(cy - rh * 0.3).toFixed(1)}" rx="${(rw * 0.6).toFixed(1)}" ry="${(rh * 0.7).toFixed(1)}" fill="${white}" opacity="${0.18 + i * 0.05}" filter="url(#bf)"/>`;
}

// ── DISTANT HILLS ──
const bY2 = bY - 4;
svg += `<path d="M0 ${bY2} Q ${w * 0.2} ${bY2 - 30 * ww} ${w * 0.4} ${bY2 - 8} T ${w} ${bY2 - 18} L ${w} ${bY} L 0 ${bY} Z" fill="${G}" opacity="0.25" filter="url(#bf)"/>`;
svg += `<path d="M0 ${bY2 - 6} Q ${w * 0.28} ${bY2 - 48 * ww} ${w * 0.55} ${bY2 - 14} T ${w} ${bY2 - 28} L ${w} ${bY} L 0 ${bY} Z" fill="${sc.bld}" opacity="0.15" filter="url(#bf)"/>`;

// ── HAVAN STOREFRONT ──
const storeW = w * 0.36;
const storeH = h * 0.32;
const storeX = (w - storeW) * 0.5;
const storeY = bY - storeH;
svg += `<rect x="${storeX}" y="${storeY}" width="${storeW}" height="${storeH}" rx="6" fill="url(#bldG)" filter="url(#sh)"/>`;
svg += `<rect x="${storeX}" y="${storeY}" width="${storeW}" height="${storeH * 0.18}" rx="6" fill="#2E1F12"/>`;
const signW = storeW * 0.50;
const signH = storeH * 0.08;
const signX = storeX + (storeW - signW) * 0.5;
const signY = storeY + storeH * 0.06;
svg += `<rect x="${signX}" y="${signY}" width="${signW}" height="${signH}" rx="3" fill="${Y}" filter="url(#sg)"/>`;
svg += `<text x="${storeX + storeW * 0.5}" y="${storeY + storeH * 0.125}" font-family="Georgia,serif" font-size="${(storeH * 0.065).toFixed(1)}" font-weight="700" fill="#2E1F12" text-anchor="middle">HAVAN</text>`;
for (let i = 0; i < 5; i++) {
  const wx = storeX + storeW * (0.08 + 0.84 * i / 4);
  const wy = storeY + storeH * 0.24;
  const ww2 = storeW * 0.13;
  const wh = storeH * 0.52;
  svg += `<rect x="${wx}" y="${wy}" width="${ww2}" height="${wh}" rx="2" fill="#1A1410" stroke="#3D2E1F" stroke-width="1.5"/>`;
  const glow = isN ? 0.5 + 0.4 * sin(mt * 1.1 + i * 0.9) : 0.7 + 0.2 * sin(mt * 0.7 + i);
  svg += `<rect x="${(wx + 2).toFixed(1)}" y="${(wy + 2).toFixed(1)}" width="${(ww2 - 4).toFixed(1)}" height="${(wh - 4).toFixed(1)}" rx="1" fill="${Y}" opacity="${clamp(glow, 0.1, 0.9).toFixed(2)}" filter="url(#sg)"/>`;
}
const doorW = storeW * 0.16;
const doorX = storeX + (storeW - doorW) * 0.5;
svg += `<rect x="${doorX}" y="${storeY + storeH * 0.24}" width="${doorW}" height="${storeH * 0.52}" rx="2" fill="#1A1410" stroke="#3D2E1F" stroke-width="1.5"/>`;
svg += `<circle cx="${(doorX + doorW - 5).toFixed(1)}" cy="${(storeY + storeH * 0.52).toFixed(1)}" r="2" fill="${Y}" opacity="0.8" filter="url(#sg)"/>`;

// ── COBBLESTONE STREET ──
const roadY = bY - 14;
svg += `<rect x="0" y="${roadY}" width="${w}" height="${bY - roadY}" fill="#495057"/>`;
for (let i = 0; i < 20; i++) {
  const sx = (i * w / 18 + sin(mt * 0.1 + i, 3)) % w;
  const sy = roadY + 4 + (i % 7) * 3 + sin(mt * 0.08 + i * 0.5, 1.5);
  svg += `<ellipse cx="${sx.toFixed(1)}" cy="${sy.toFixed(1)}" rx="${(5 + (i % 3) * 2).toFixed(1)}" ry="2.5" fill="url(#stripeG)" opacity="0.5"/>`;
}
svg += `<rect x="0" y="${roadY}" width="${w}" height="3" fill="#6C757D" opacity="0.7"/>`;
svg += `<rect x="0" y="${(roadY + 3).toFixed(1)}" width="${w}" height="2" fill="#343A40" opacity="0.4"/>`;

// ── PALM TREES ──
for (let side of [-1, 1]) {
  const tx = (side === -1 ? w * 0.08 : w * 0.92);
  const sway = sin(mt * 0.7 + side * 0.5, 3);
  const trunkH = 70 * ww;
  svg += `<path d="M${tx} ${bY - 4} Q ${tx + sway} ${bY - trunkH * 0.5} ${tx + sway * 1.3} ${bY - trunkH}" stroke="#5C4033" stroke-width="${(6 * ww).toFixed(1)}" fill="none" stroke-linecap="round" filter="url(#sh)"/>`;
  for (let k = 0; k < 5; k++) {
    const ang = -1.8 + k * 0.9 + sin(mt * 0.6 + side + k, 0.04);
    const lx = tx + sway * 1.3 + cos(ang, 26 * ww);
    const ly = bY - trunkH + sin(ang, 18 * ww);
    svg += `<line x1="${(tx + sway * 1.3).toFixed(1)}" y1="${(bY - trunkH).toFixed(1)}" x2="${lx.toFixed(1)}" y2="${ly.toFixed(1)}" stroke="#2E7D52" stroke-width="${(3 * ww).toFixed(1)}" stroke-linecap="round"/>`;
  }
}

// ── STREET LAMPS ──
for (let side of [-1, 1]) {
  const lx = side === -1 ? w * 0.12 : w * 0.88;
  const ly = bY - 2;
  svg += `<rect x="${(lx - 2).toFixed(1)}" y="${(ly - 48 * ww).toFixed(1)}" width="${(4 * ww).toFixed(1)}" height="${(48 * ww).toFixed(1)}" fill="#6C757D" filter="url(#sh)"/>`;
  svg += `<path d="M${(lx - 14 * ww).toFixed(1)} ${(ly - 48 * ww).toFixed(1)} Q${lx} ${(ly - 56 * ww).toFixed(1)} ${(lx + 14 * ww).toFixed(1)} ${(ly - 48 * ww).toFixed(1)}" fill="none" stroke="#6C757D" stroke-width="${(3 * ww).toFixed(1)}"/>`;
  const lampGlow = isN ? 0.6 + 0.3 * sin(mt * 1.8 + side) : 0.2;
  svg += `<circle cx="${lx}" cy="${(ly - 48 * ww).toFixed(1)}" r="${(6 * ww).toFixed(1)}" fill="${Y}" opacity="${lampGlow.toFixed(2)}" filter="url(#fg)"/>`;
  svg += `<circle cx="${lx}" cy="${(ly - 48 * ww).toFixed(1)}" r="${(18 * ww).toFixed(1)}" fill="${Y}" opacity="${(lampGlow * 0.15).toFixed(2)}" filter="url(#fg)"/>`;
}

// ═══════════════════════════════════════════════════
// ── HERO: FIAT HAVAN CAR ──
// ═══════════════════════════════════════════════════
const cx = w * 0.5;
const cy = bY - 28;
const s = 1.8;
const col = Y;
const happy = true;
const ol2 = Math.max(1.5 * s, 1);

const bob = sin(mt * 2.2, 2 * s);
const blink = sin(mt * 1.3) > 0.96 ? 0.15 : 1;
const glow2 = 0.55 + sin(mt * 3) * 0.2;
const smile = happy ? 5 * s : 1 * s;

const bodyY = cy + bob;

svg += `<ellipse cx="${cx}" cy="${(bodyY + 30 * s).toFixed(1)}" rx="${(48 * s).toFixed(1)}" ry="${(8 * s).toFixed(1)}" fill="rgba(0,0,0,0.3)" filter="url(#sh)"/>`;
for (let side of [-1, 1]) {
  svg += `<circle cx="${(cx + side * 42 * s).toFixed(1)}" cy="${(bodyY + 24 * s).toFixed(1)}" r="${(10 * s).toFixed(1)}" fill="#161616" stroke="#000" stroke-width="${(ol2 * 0.4).toFixed(1)}"/>`;
  svg += `<circle cx="${(cx + side * 42 * s).toFixed(1)}" cy="${(bodyY + 24 * s).toFixed(1)}" r="${(4 * s).toFixed(1)}" fill="#8a8a8a"/>`;
}
for (let side of [-1, 1]) {
  svg += `<ellipse cx="${(cx + side * 48 * s).toFixed(1)}" cy="${(bodyY - 28 * s).toFixed(1)}" rx="${(3.5 * s).toFixed(1)}" ry="${(4.5 * s).toFixed(1)}" fill="#141414"/>`;
}
svg += `<path d="M ${(cx - 48 * s).toFixed(1)} ${(bodyY - 36 * s).toFixed(1)} Q ${(cx - 50 * s).toFixed(1)} ${(bodyY - 10 * s).toFixed(1)} ${(cx - 44 * s).toFixed(1)} ${(bodyY + 8 * s).toFixed(1)} Q ${(cx - 40 * s).toFixed(1)} ${(bodyY + 20 * s).toFixed(1)} ${(cx - 22 * s).toFixed(1)} ${(bodyY + 24 * s).toFixed(1)} L ${(cx + 22 * s).toFixed(1)} ${(bodyY + 24 * s).toFixed(1)} Q ${(cx + 40 * s).toFixed(1)} ${(bodyY + 20 * s).toFixed(1)} ${(cx + 44 * s).toFixed(1)} ${(bodyY + 8 * s).toFixed(1)} Q ${(cx + 50 * s).toFixed(1)} ${(bodyY - 10 * s).toFixed(1)} ${(cx + 48 * s).toFixed(1)} ${(bodyY - 36 * s).toFixed(1)} Q ${(cx + 32 * s).toFixed(1)} ${(bodyY - 46 * s).toFixed(1)} ${cx} ${(bodyY - 48 * s).toFixed(1)} Q ${(cx - 32 * s).toFixed(1)} ${(bodyY - 46 * s).toFixed(1)} ${(cx - 48 * s).toFixed(1)} ${(bodyY - 36 * s).toFixed(1)} Z" fill="${col}" stroke="#8a6200" stroke-width="${ol2.toFixed(1)}" filter="url(#sh)"/>`;
svg += `<path d="M ${(cx - 32 * s).toFixed(1)} ${(bodyY - 46 * s).toFixed(1)} Q ${cx} ${(bodyY - 54 * s).toFixed(1)} ${(cx + 32 * s).toFixed(1)} ${(bodyY - 46 * s).toFixed(1)} L ${(cx + 28 * s).toFixed(1)} ${(bodyY - 42 * s).toFixed(1)} Q ${cx} ${(bodyY - 48 * s).toFixed(1)} ${(cx - 28 * s).toFixed(1)} ${(bodyY - 42 * s).toFixed(1)} Z" fill="#141414"/>`;
const glass = '#222c36';
for (let side of [-1, 1]) {
  const cx2 = side * 14 * s;
  svg += `<path d="M ${(cx + cx2 - 12 * s).toFixed(1)} ${(bodyY - 42 * s).toFixed(1)} L ${(cx + cx2 + 14 * s).toFixed(1)} ${(bodyY - 42 * s).toFixed(1)} L ${(cx + cx2 + 12 * s).toFixed(1)} ${(bodyY - 34 * s).toFixed(1)} L ${(cx + cx2 - 10 * s).toFixed(1)} ${(bodyY - 34 * s).toFixed(1)} Z" fill="${glass}" stroke="#141414" stroke-width="${(ol2 * 0.4).toFixed(1)}"/>`;
}
svg += `<rect x="${(cx - 2 * s).toFixed(1)}" y="${(bodyY - 42 * s).toFixed(1)}" width="${(4 * s).toFixed(1)}" height="${(8 * s).toFixed(1)}" fill="#141414"/>`;
svg += `<rect x="${(cx - 19 * s).toFixed(1)}" y="${(bodyY - 28 * s).toFixed(1)}" width="${(38 * s).toFixed(1)}" height="${(22 * s).toFixed(1)}" rx="${(2.5 * s).toFixed(1)}" fill="#0a0a0a" stroke="#000" stroke-width="${(ol2 * 0.3).toFixed(1)}"/>`;
for (let i = -2; i <= 2; i++) {
  svg += `<line x1="${(cx + i * 6.5 * s).toFixed(1)}" y1="${(bodyY - 26 * s).toFixed(1)}" x2="${(cx + i * 6.5 * s).toFixed(1)}" y2="${(bodyY - 8 * s).toFixed(1)}" stroke="#2b2b2b" stroke-width="${(ol2 * 0.3).toFixed(1)}"/>`;
}
const colors = ['#c0454f', '#c9c9c9', '#c0454f'];
for (let i of [-1, 0, 1]) {
  svg += `<rect x="${(cx + i * 3.5 * s - 1.2 * s).toFixed(1)}" y="${(bodyY - 25 * s).toFixed(1)}" width="${(2.4 * s).toFixed(1)}" height="${(18 * s).toFixed(1)}" fill="${colors[i + 1]}"/>`;
}
svg += `<circle cx="${cx}" cy="${(bodyY - 31 * s).toFixed(1)}" r="${(2.5 * s).toFixed(1)}" fill="#d6d6d6" stroke="#333" stroke-width="${(ol2 * 0.2).toFixed(1)}"/>`;
for (let side of [-1, 1]) {
  const hx = cx + side * 38 * s;
  svg += `<circle cx="${hx.toFixed(1)}" cy="${(bodyY - 20 * s).toFixed(1)}" r="${(9 * s).toFixed(1)}" fill="#3a3a3a" stroke="#141414" stroke-width="${(ol2 * 0.4).toFixed(1)}"/>`;
  svg += `<circle cx="${hx.toFixed(1)}" cy="${(bodyY - 20 * s).toFixed(1)}" r="${(6.5 * s).toFixed(1)}" fill="#fff4c2" opacity="${glow2.toFixed(2)}"/>`;
  if (happy) {
    svg += `<ellipse cx="${hx.toFixed(1)}" cy="${(bodyY - 20 * s).toFixed(1)}" rx="${(2.2 * s).toFixed(1)}" ry="${(2.2 * s * blink).toFixed(1)}" fill="#222"/>`;
  }
}
for (let side of [-1, 1]) {
  svg += `<rect x="${(cx + side * 48 * s - (side > 0 ? 8 : 0) * s).toFixed(1)}" y="${(bodyY - 14 * s).toFixed(1)}" width="${(8 * s).toFixed(1)}" height="${(6 * s).toFixed(1)}" rx="${(1.5 * s).toFixed(1)}" fill="#ff8c1a" stroke="#7a3d00" stroke-width="${(ol2 * 0.25).toFixed(1)}"/>`;
}
svg += `<path d="M ${(cx - 46 * s).toFixed(1)} ${(bodyY - 2 * s).toFixed(1)} Q ${cx} ${(bodyY - 2 * s + smile).toFixed(1)} ${(cx + 46 * s).toFixed(1)} ${(bodyY - 2 * s).toFixed(1)} L ${(cx + 46 * s).toFixed(1)} ${(bodyY + 4 * s).toFixed(1)} Q ${cx} ${(bodyY + 4 * s + smile).toFixed(1)} ${(cx - 46 * s).toFixed(1)} ${(bodyY + 4 * s).toFixed(1)} Z" fill="#c9cdd0" stroke="#6e7275" stroke-width="${(ol2 * 0.3).toFixed(1)}"/>`;
svg += `<rect x="${(cx - 15 * s).toFixed(1)}" y="${(bodyY + 6 * s).toFixed(1)}" width="${(30 * s).toFixed(1)}" height="${(10 * s).toFixed(1)}" rx="${(1.5 * s).toFixed(1)}" fill="#f2f1ef" stroke="#333" stroke-width="${(ol2 * 0.25).toFixed(1)}"/>`;
svg += `<text x="${cx}" y="${(bodyY + 13.5 * s).toFixed(1)}" font-family="Arial, sans-serif" font-weight="bold" font-size="${(7 * s).toFixed(1)}" fill="#111" text-anchor="middle">HAVAN</text>`;
svg += `<rect x="${(cx - 42 * s).toFixed(1)}" y="${(bodyY + 15 * s).toFixed(1)}" width="${(84 * s).toFixed(1)}" height="${(6 * s).toFixed(1)}" rx="${(2.5 * s).toFixed(1)}" fill="#111"/>`;

// ── SPARKLE ACCENTS ──
svg += `<circle cx="${(cx - 54 * s).toFixed(1)}" cy="${(bodyY - 48 * s).toFixed(1)}" r="${(2.5 * s).toFixed(1)}" fill="#FFD700" opacity="${(0.4 + sin(mt * 4) * 0.2).toFixed(2)}" filter="url(#fg)"/>`;
svg += `<circle cx="${(cx + 52 * s).toFixed(1)}" cy="${(bodyY - 42 * s).toFixed(1)}" r="${(1.8 * s).toFixed(1)}" fill="#FFD700" opacity="${(0.3 + sin(mt * 3.5 + 1) * 0.2).toFixed(2)}" filter="url(#sg)"/>`;

// ── FLOATING CONFETTI ──
for (let i = 0; i < 8; i++) {
  const px = (w * ((i * 0.14 + 0.03) % 1) + sin(mt * 0.3 + i * 1.2, 12 * ww)) % w;
  const py = (h * 0.3 + (mt * 20 + i * 60) % (h * 0.55));
  const pr = 1.5 + (i % 3) * 1.2;
  const cc = i % 3 === 0 ? Y : i % 3 === 1 ? '#FF6B6B' : '#4ECDC4';
  svg += `<circle cx="${px.toFixed(1)}" cy="${py.toFixed(1)}" r="${pr.toFixed(1)}" fill="${cc}" opacity="${(0.35 + sin(mt * 1.2 + i) * 0.15).toFixed(2)}" filter="url(#sg)"/>`;
}

return svg;
